cat > output/styles.css <<'CSS'
:root{
  --bg:#0A0A0A;
  --panel:#0F1012;
  --panel2:#121318;
  --border:rgba(255,255,255,.10);
  --border2:rgba(255,255,255,.16);
  --text:rgba(255,255,255,.92);
  --muted:rgba(255,255,255,.68);
  --muted2:rgba(255,255,255,.52);
  --accent:#4C8BFF;   /* electric blue */
  --accent2:#FFB050;  /* warm amber */
  --shadow: 0 16px 48px rgba(0,0,0,.55);
  --shadow2: 0 10px 30px rgba(0,0,0,.45);
  --radius:18px;
  --radius2:26px;
  --container: min(1120px, calc(100vw - 48px));
}

*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;
  background: radial-gradient(1200px 700px at 70% -10%, rgba(76,139,255,.18), transparent 55%),
              radial-gradient(900px 600px at 10% 10%, rgba(255,176,80,.10), transparent 55%),
              var(--bg);
  color:var(--text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji","Segoe UI Emoji";
  line-height:1.5;
  letter-spacing:-0.01em;
}

a{color:inherit; text-decoration:none}
a:hover{color:rgba(255,255,255,.98)}

.container{width:var(--container); margin:0 auto}

/* Accessibility */
.sr-only{position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0}
.skip-link{position:absolute; left:12px; top:12px; padding:10px 12px; background:#111; border:1px solid var(--border2); border-radius:12px; transform:translateY(-140%); transition:transform .2s ease; z-index:10000}
.skip-link:focus{transform:translateY(0)}

/* Header */
.header{
  position:sticky; top:0; z-index:1000;
  backdrop-filter: blur(10px);
  background: rgba(10,10,10,.72);
  border-bottom: 1px solid rgba(255,255,255,.08);
}
.header-inner{display:flex; align-items:center; justify-content:space-between; gap:18px; padding:14px 0}
.brand{display:flex; align-items:center; gap:10px}
.brand-mark{
  width:34px; height:34px; border-radius:12px;
  background: radial-gradient(14px 14px at 30% 30%, rgba(255,255,255,.35), transparent 60%),
              linear-gradient(135deg, rgba(76,139,255,.9), rgba(255,176,80,.65));
  box-shadow: 0 10px 24px rgba(0,0,0,.35);
}
.brand-name{font-weight:650; letter-spacing:0.06em; text-transform:uppercase; font-size:13px; color:rgba(255,255,255,.92)}

.nav{display:flex; align-items:center; gap:18px}
.nav a{font-size:13px; color:rgba(255,255,255,.78)}
.nav a:hover{color:rgba(255,255,255,.95)}

.header-actions{display:flex; align-items:center; gap:10px}

.btn{
  display:inline-flex; align-items:center; justify-content:center; gap:8px;
  border-radius:999px;
  border:1px solid var(--border2);
  padding:10px 14px;
  background: rgba(255,255,255,.04);
  color:rgba(255,255,255,.88);
  font-size:13px;
  cursor:pointer;
  transition: transform .15s ease, background .15s ease, border-color .15s ease;
}
.btn:hover{background: rgba(255,255,255,.06); border-color: rgba(255,255,255,.22)}
.btn:active{transform: translateY(1px)}
.btn.primary{
  background: linear-gradient(135deg, rgba(76,139,255,.92), rgba(76,139,255,.62));
  border-color: rgba(76,139,255,.55);
  color: #07101f;
  font-weight:650;
}
.btn.primary:hover{background: linear-gradient(135deg, rgba(76,139,255,1), rgba(76,139,255,.72))}

.icon{
  width:18px; height:18px; display:inline-block;
  fill:none; stroke:currentColor; stroke-width:2; stroke-linecap:round; stroke-linejoin:round;
}

/* Mobile nav */
.burger{display:none}
.mobile-panel{
  display:none;
  border-top:1px solid rgba(255,255,255,.08);
  padding:10px 0 18px;
}
.mobile-panel a{display:block; padding:12px 6px; color:rgba(255,255,255,.82); font-size:14px}
.mobile-panel a:hover{background: rgba(255,255,255,.04); border-radius:12px}

/* Language dropdown */
.dropdown{position:relative}
.dropdown-panel{
  position:absolute; right:0; top:46px;
  width:220px;
  border-radius:16px;
  background: rgba(18,19,24,.98);
  border:1px solid rgba(255,255,255,.12);
  box-shadow: var(--shadow2);
  padding:8px;
  display:none;
}
.dropdown[aria-expanded="true"] .dropdown-panel{display:block}
.dropdown-panel button{
  width:100%; text-align:left;
  border:0; background:transparent;
  padding:10px 10px;
  border-radius:12px;
  color: rgba(255,255,255,.82);
  cursor:pointer;
}
.dropdown-panel button:hover{background: rgba(255,255,255,.06)}
.dropdown-panel .hint{padding:8px 10px 2px; color:rgba(255,255,255,.52); font-size:12px}

/* Sections */
.section{padding:84px 0}
.section-title{display:flex; align-items:end; justify-content:space-between; gap:16px; margin-bottom:18px}
.section-title h2{margin:0; font-size:34px; letter-spacing:-0.03em; line-height:1.15}
.section-title p{margin:0; max-width:560px; color:var(--muted); font-size:15px}

.kicker{display:inline-flex; gap:10px; align-items:center; color:rgba(255,255,255,.65); font-size:13px; letter-spacing:.18em; text-transform:uppercase}
.kicker .dot{width:8px; height:8px; border-radius:99px; background: var(--accent)}

/* Hero */
.hero{padding:44px 0 54px}
.hero-grid{display:grid; grid-template-columns: 1.05fr .95fr; gap:22px; align-items:stretch}
.hero-copy{
  border-radius: var(--radius2);
  border: 1px solid rgba(255,255,255,.10);
  background: linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
  box-shadow: var(--shadow2);
  padding:28px;
  overflow:hidden;
  position:relative;
}
.hero-copy:before{
  content:""; position:absolute; inset:-140px -120px auto auto; width:420px; height:420px;
  background: radial-gradient(circle at 30% 30%, rgba(76,139,255,.22), transparent 60%);
  filter: blur(0px);
}
.hero-copy h1{margin:14px 0 12px; font-size:54px; line-height:1.02; letter-spacing:-0.05em}
.hero-copy .lead{margin:0 0 18px; color:rgba(255,255,255,.70); font-size:16px; max-width:50ch}
.hero-metrics{display:grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap:10px; margin:22px 0 0}
.metric{border:1px solid rgba(255,255,255,.10); border-radius:16px; padding:12px 12px; background: rgba(0,0,0,.18)}
.metric .v{font-size:18px; font-weight:700; letter-spacing:-0.02em}
.metric .l{font-size:12px; color:rgba(255,255,255,.62)}

.hero-carousel{
  border-radius: var(--radius2);
  border: 1px solid rgba(255,255,255,.10);
  background: rgba(255,255,255,.02);
  box-shadow: var(--shadow2);
  overflow:hidden;
  position:relative;
}
.carousel-viewport{overflow:hidden}
.carousel-track{display:flex; transition: transform 560ms cubic-bezier(.2,.8,.2,1); will-change:transform}
.slide{min-width:100%; padding:18px; display:grid; grid-template-rows: 220px auto; gap:16px}
.slide-media{border-radius:20px; overflow:hidden; border:1px solid rgba(255,255,255,.10); background:#0f0f12}
.slide-media img{width:100%; height:100%; object-fit:cover; display:block; opacity:.92}
.slide-card{
  border-radius:20px;
  border:1px solid rgba(255,255,255,.10);
  background: linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
  padding:16px;
}
.slide-card .title{font-size:18px; font-weight:650; letter-spacing:-0.02em; margin:0 0 8px}
.slide-card .desc{margin:0 0 12px; color:rgba(255,255,255,.68); font-size:14px}

.carousel-controls{display:flex; align-items:center; justify-content:space-between; padding:12px 14px; border-top:1px solid rgba(255,255,255,.08)}
.dots{display:flex; gap:8px; align-items:center}
.dot-btn{width:8px; height:8px; border-radius:999px; border:0; background: rgba(255,255,255,.25); cursor:pointer; padding:0}
.dot-btn[aria-current="true"]{background: var(--accent); width:26px}

/* Team */
.tabs{display:flex; gap:8px; flex-wrap:wrap}
.tab{
  border:1px solid rgba(255,255,255,.14);
  background: rgba(255,255,255,.03);
  color: rgba(255,255,255,.78);
  padding:10px 12px;
  border-radius: 999px;
  font-size:13px;
  cursor:pointer;
  transition: background .15s ease, border-color .15s ease;
}
.tab[aria-selected="true"]{background: rgba(76,139,255,.14); border-color: rgba(76,139,255,.45); color: rgba(255,255,255,.92)}

.hscroll{
  display:grid; grid-auto-flow:column; grid-auto-columns: minmax(320px, 360px);
  gap:14px;
  overflow:auto;
  padding-bottom:8px;
  scroll-snap-type:x mandatory;
  -webkit-overflow-scrolling:touch;
}
.hscroll::-webkit-scrollbar{height:10px}
.hscroll::-webkit-scrollbar-thumb{background: rgba(255,255,255,.14); border-radius:999px}
.hscroll::-webkit-scrollbar-track{background: rgba(255,255,255,.06); border-radius:999px}

.card{
  scroll-snap-align:start;
  border-radius: var(--radius);
  border:1px solid rgba(255,255,255,.10);
  background: linear-gradient(180deg, rgba(255,255,255,.03), rgba(255,255,255,.015));
  box-shadow: var(--shadow2);
  overflow:hidden;
}
.card .img{height:220px; border-bottom:1px solid rgba(255,255,255,.08)}
.card .img img{width:100%; height:100%; object-fit:cover; display:block; opacity:.90}
.card .body{padding:16px}
.card .meta{display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:10px}
.badge{font-size:12px; color: rgba(255,255,255,.74); padding:6px 10px; border:1px solid rgba(255,255,255,.12); border-radius:999px; background: rgba(0,0,0,.18)}
.card h3{margin:0; font-size:18px; letter-spacing:-0.02em}
.card .role{margin:6px 0 10px; color: rgba(255,255,255,.68); font-size:13px}
.quote{margin:0 0 14px; color: rgba(255,255,255,.74); font-size:14px}
.quote:before{content:"“"; color: rgba(255,255,255,.45)}
.quote:after{content:"”"; color: rgba(255,255,255,.45)}

/* Work */
.work-card .img{height:200px}
.work-card .desc{color: rgba(255,255,255,.68); font-size:13px; margin:0 0 12px}

/* CTA Banner */
.banner{
  border-radius: 28px;
  border: 1px solid rgba(255,255,255,.10);
  background: radial-gradient(800px 280px at 20% 0%, rgba(76,139,255,.22), transparent 60%),
              radial-gradient(760px 240px at 90% 20%, rgba(255,176,80,.16), transparent 55%),
              linear-gradient(180deg, rgba(255,255,255,.035), rgba(255,255,255,.02));
  padding:24px;
  box-shadow: var(--shadow);
  display:flex; align-items:center; justify-content:space-between; gap:18px;
}
.banner h3{margin:0 0 8px; font-size:26px; letter-spacing:-0.03em}
.banner p{margin:0; color: rgba(255,255,255,.72); max-width:68ch}

/* How we work */
.split{display:grid; grid-template-columns: 1fr 1fr; gap:18px; align-items:stretch}
.panel{
  border-radius: var(--radius2);
  border:1px solid rgba(255,255,255,.10);
  background: rgba(255,255,255,.02);
  box-shadow: var(--shadow2);
  padding:22px;
  overflow:hidden;
}
.panel h3{margin:0 0 10px; font-size:28px; letter-spacing:-0.03em}
.panel p{margin:0 0 16px; color: rgba(255,255,255,.70)}

.service-grid{display:grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap:12px}
.service{
  border-radius:18px;
  border:1px solid rgba(255,255,255,.10);
  background: rgba(0,0,0,.18);
  padding:14px;
}
.service .t{margin:0 0 6px; font-weight:650}
.service .d{margin:0; color: rgba(255,255,255,.66); font-size:13px}

/* Insights */
.grid{display:grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap:14px}
.insight-card .img{height:160px}
.small{font-size:12px; color: rgba(255,255,255,.60)}

/* Principles */
.principles{display:grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap:14px}
.principle{position:relative}
.principle:before{
  content:"";
  position:absolute; inset: -1px;
  border-radius: var(--radius2);
  background: linear-gradient(135deg, rgba(76,139,255,.40), rgba(255,176,80,.22), rgba(255,255,255,.08));
  opacity:.18;
  filter: blur(0px);
  z-index:0;
}
.principle .panel{position:relative; z-index:1}

/* Footer */
.footer{padding:40px 0 60px; border-top:1px solid rgba(255,255,255,.08)}
.footer-top{display:grid; grid-template-columns: 1.2fr .8fr; gap:14px; margin-bottom:20px}
.footer-ctas{display:grid; gap:12px}
.footer-card{border-radius:22px; border:1px solid rgba(255,255,255,.10); background: rgba(255,255,255,.02); padding:18px}
.footer-card p{margin:0 0 12px; color: rgba(255,255,255,.72)}
.footer-links{display:flex; flex-wrap:wrap; gap:14px; padding-top:8px}
.footer-links a{color: rgba(255,255,255,.70); font-size:13px}
.footer-links a:hover{color: rgba(255,255,255,.92)}
.legal{display:flex; flex-wrap:wrap; gap:10px; justify-content:space-between; color: rgba(255,255,255,.56); font-size:12px; margin-top:18px}

/* Cookie banner */
.cookie{
  position:fixed; left:16px; right:16px; bottom:16px;
  max-width: 1120px;
  margin:0 auto;
  border-radius: 22px;
  border:1px solid rgba(255,255,255,.14);
  background: rgba(18,19,24,.92);
  box-shadow: var(--shadow);
  padding:16px;
  display:none;
  z-index:2000;
}
.cookie.show{display:block}
.cookie-row{display:flex; align-items:flex-start; justify-content:space-between; gap:14px}
.cookie h4{margin:0 0 6px; font-size:16px}
.cookie p{margin:0; color: rgba(255,255,255,.70); font-size:13px; max-width:75ch}
.cookie-actions{display:flex; flex-wrap:wrap; gap:10px; justify-content:flex-end}

.modal-backdrop{
  position:fixed; inset:0;
  background: rgba(0,0,0,.62);
  display:none;
  z-index:2100;
}
.modal-backdrop.show{display:block}
.modal{
  position:fixed;
  left:50%; top:50%; transform: translate(-50%,-50%);
  width:min(720px, calc(100vw - 36px));
  border-radius: 24px;
  border:1px solid rgba(255,255,255,.14);
  background: rgba(16,17,20,.96);
  box-shadow: var(--shadow);
  padding:18px;
}
.modal h3{margin:0 0 6px; font-size:18px}
.modal p{margin:0 0 14px; color: rgba(255,255,255,.70); font-size:13px}
.modal .rows{display:grid; gap:10px; margin:12px 0 16px}
.toggle{
  display:flex; align-items:center; justify-content:space-between; gap:12px;
  border-radius: 18px;
  border:1px solid rgba(255,255,255,.12);
  background: rgba(0,0,0,.18);
  padding:12px;
}
.toggle .t{font-weight:650}
.toggle .d{color: rgba(255,255,255,.62); font-size:12px}
.switch{
  width:46px; height:28px; border-radius:999px;
  background: rgba(255,255,255,.18);
  border:1px solid rgba(255,255,255,.18);
  position:relative;
  cursor:pointer;
}
.switch:before{
  content:""; position:absolute; top:3px; left:3px;
  width:22px; height:22px; border-radius:999px;
  background: rgba(255,255,255,.85);
  transition: transform .18s ease;
}
.switch[aria-checked="true"]{background: rgba(76,139,255,.35); border-color: rgba(76,139,255,.55)}
.switch[aria-checked="true"]:before{transform: translateX(18px)}

/* Responsive */
@media (max-width: 980px){
  .hero-grid{grid-template-columns: 1fr}
  .split{grid-template-columns: 1fr}
  .grid{grid-template-columns: repeat(2, minmax(0,1fr))}
  .footer-top{grid-template-columns: 1fr}
}

@media (max-width: 720px){
  .nav{display:none}
  .burger{display:inline-flex}
  .mobile-panel.open{display:block}

  .hero-copy h1{font-size:44px}
  .hero-metrics{grid-template-columns: 1fr 1fr}

  .section{padding:66px 0}
  .section-title{flex-direction:column; align-items:flex-start}

  .grid{grid-template-columns: 1fr}
  .principles{grid-template-columns: 1fr}

  .banner{flex-direction:column; align-items:flex-start}
  .cookie-row{flex-direction:column}
  .cookie-actions{justify-content:flex-start}
}

@media (prefers-reduced-motion: reduce){
  *{scroll-behavior:auto !important}
  .carousel-track{transition:none}
  .btn{transition:none}
}
