    if(closeSettings) closeSettings.addEventListener('click', hideModal);
    if(modalBackdrop) modalBackdrop.addEventListener('click', hideModal);
    document.addEventListener('keydown', (e) => { if(e.key === 'Escape') hideModal(); });

